function dashboardPage() {
  return `<main class="page"><div class="page-heading"><div><span class="section-kicker">Overview / 07 Nov 2026</span><h1>Good morning, Alex.</h1><p>Your experiment workspace is quiet, healthy, and ready for the next question.</p></div><div class="page-heading-actions"><button class="btn btn-ghost" data-action="nav" data-view="datasets">${icon('database', 14)} Browse datasets</button><button class="btn btn-primary" data-action="open-upload">${icon('plus', 14)} Add dataset</button></div></div><div class="metric-grid"><div class="metric-card"><div class="metric-label"><span>Total datasets</span>${icon('database', 14)}</div><div class="metric-value">04</div><span class="metric-change">${icon('arrowUp', 11)} 2 this month</span></div><div class="metric-card violet"><div class="metric-label"><span>Experiments</span>${icon('flask', 14)}</div><div class="metric-value">18</div><span class="metric-change">${icon('arrowUp', 11)} 24% vs last month</span></div><div class="metric-card green"><div class="metric-label"><span>Trained models</span>${icon('tree', 14)}</div><div class="metric-value">12</div><span class="metric-change">${icon('arrowUp', 11)} 4 ready to review</span></div><div class="metric-card amber"><div class="metric-label"><span>Avg. accuracy</span>${icon('chart', 14)}</div><div class="metric-value">92.8%</div><span class="metric-change muted">Illustrative benchmark</span></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Experiment performance</h2><p class="panel-subtitle">Best validation accuracy across recent runs</p></div><span class="tag blue">LAST 30 DAYS</span></div><div id="dashboard-performance-chart" class="chart-holder"></div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recent activity</h2><p class="panel-subtitle">A short trail of your lab work</p></div><button class="icon-btn" data-action="workspace-tab" data-tab="history" aria-label="Open experiment history">${icon('external', 14)}</button></div><div class="activity-list"><div class="activity-row"><span class="activity-icon">${icon('check', 14)}</span><div><strong>Random Forest completed</strong><span>Iris Dataset · accuracy 97.3%</span></div><span class="activity-time">9m</span></div><div class="activity-row"><span class="activity-icon" style="color:#c5b4fc;background:var(--violet-soft)">${icon('spark', 14)}</span><div><strong>AutoML search completed</strong><span>Customer Churn · 12 candidates</span></div><span class="activity-time">2h</span></div><div class="activity-row"><span class="activity-icon" style="color:#f6c978;background:var(--amber-soft)">${icon('upload', 14)}</span><div><strong>juice Dataset profiled</strong><span>13 features · no missing values</span></div><span class="activity-time">1d</span></div><div class="activity-row"><span class="activity-icon">${icon('settings', 14)}</span><div><strong>Preprocessing updated</strong><span>Breast Cancer Wisconsin</span></div><span class="activity-time">1d</span></div></div></section></div><section class="panel" style="margin-bottom:13px"><div class="panel-header"><div><h2 class="panel-title">Recent datasets</h2><p class="panel-subtitle">Open any dataset to continue where you left off</p></div><button class="btn btn-ghost btn-sm" data-action="nav" data-view="datasets">View all ${icon('arrow', 12)}</button></div><div class="dataset-mini-list">${datasets.map(d => `<button class="dataset-mini" data-action="open-dataset" data-id="${d.id}" style="text-align:left;color:inherit"><span class="dataset-icon" style="${d.accent === 'violet' ? 'color:#c5b4fc;background:var(--violet-soft)' : d.accent === 'green' ? 'color:#69e1b5;background:var(--emerald-soft)' : d.accent === 'amber' ? 'color:#f6c978;background:var(--amber-soft)' : ''}">${icon('database', 15)}</span><strong>${esc(d.name)}</strong><small>${d.rows} rows · ${d.features} features</small></button>`).join('')}</div></section><div class="two-col"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Quick actions</h2><p class="panel-subtitle">Common next steps in your research loop</p></div></div><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px"><button class="btn btn-secondary" data-action="open-upload">${icon('upload', 14)} Upload dataset</button><button class="btn btn-ghost" data-action="workspace-tab" data-tab="preprocess">${icon('settings', 14)} Configure pipeline</button><button class="btn btn-ghost" data-action="workspace-tab" data-tab="models">${icon('tree', 14)} Train a model</button><button class="btn btn-violet" data-action="workspace-tab" data-tab="automl">${icon('spark', 14)} Launch AutoML</button></div></section><section class="panel panel-accent green"><div class="panel-header"><div><h2 class="panel-title">Prototype note</h2><p class="panel-subtitle">A clear boundary for technical review</p></div><span class="tag green">READY</span></div><p style="margin:0;color:var(--text-soft);font-size:11px;line-height:1.7">TreeLab is intentionally a frontend experience. Every metric, chart, and progress state is seeded mock data designed to make the future application easier to discuss.</p></section></div></main>`;
}

function datasetsPage() {
  const filtered = datasets.filter(d => (!state.search || `${d.name} ${d.type} ${d.target}`.toLowerCase().includes(state.search.toLowerCase())) && (state.filter === 'All datasets' || d.type === state.filter));
  return `<main class="page"><div class="page-heading"><div><span class="section-kicker">Workspace / datasets</span><h1>My Datasets</h1><p>Keep the inputs of your experiments legible, searchable, and close at hand.</p></div><div class="page-heading-actions"><span class="tag amber">${datasets.length} DATASETS · SESSION ONLY</span><button class="btn btn-primary" data-action="open-upload">${icon('upload', 14)} Upload CSV</button></div></div><div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${icon('search', 14)}<input id="dataset-search" value="${esc(state.search)}" placeholder="Search datasets, targets, or types" aria-label="Search datasets" /></label><select class="select" id="dataset-filter" aria-label="Filter datasets"><option ${state.filter === 'All datasets' ? 'selected' : ''}>All datasets</option><option ${state.filter === 'Classification' ? 'selected' : ''}>Classification</option><option ${state.filter === 'Binary classification' ? 'selected' : ''}>Binary classification</option></select></div><div class="toolbar-right"><span class="tag blue">${icon('database', 11)} 4 built-in samples</span><button class="icon-btn" data-action="notify-demo" aria-label="Dataset library info">${icon('info', 14)}</button></div></div>${filtered.length ? `<div class="dataset-table"><div class="table-head"><span>Dataset</span><span>Task</span><span>Rows</span><span>Features</span><span>Updated</span><span></span></div>${filtered.map(d => `<div class="dataset-row"><div class="dataset-name"><span class="dataset-icon" style="margin:0;flex:0 0 auto;${d.accent === 'violet' ? 'color:#c5b4fc;background:var(--violet-soft)' : d.accent === 'green' ? 'color:#69e1b5;background:var(--emerald-soft)' : d.accent === 'amber' ? 'color:#f6c978;background:var(--amber-soft)' : ''}">${icon('database', 15)}</span><div><strong>${esc(d.name)}</strong><span>Target: <span class="mono">${esc(d.target)}</span> · ${esc(d.description)}</span></div></div><span class="dataset-type">${esc(d.type)}</span><span class="table-cell mono">${d.rows}</span><span class="table-cell mono">${d.features}</span><span class="table-cell">${d.updated}</span><div class="row-actions"><button class="icon-btn" data-action="open-dataset" data-id="${d.id}" aria-label="Open ${esc(d.name)}">${icon('arrow', 14)}</button><button class="icon-btn" data-action="dataset-menu" data-id="${d.id}" aria-label="Dataset actions">${icon('dots', 14)}</button></div></div>`).join('')}</div>` : `<div class="empty-state"><span class="feature-icon">${icon('search', 17)}</span><h3>No datasets match that query</h3><p>Try a different search term or clear the filter. Uploaded datasets are session-only in this prototype.</p><button class="btn btn-ghost btn-sm" data-action="clear-dataset-search">Clear search</button></div>`}</main>`;
}

function workspacePage() {
  const d = selectedDataset();
  const tabs = [['overview','Overview'], ['explorer','Data Explorer'], ['preprocess','Preprocessing Studio'], ['models','Model Laboratory'], ['automl','AutoML Laboratory'], ['compare','Model Comparison'], ['explain','Explainability Studio'], ['history','Experiment History']];
  return `<main class="page"><section class="workspace-heading"><div class="workspace-identity"><span class="dataset-icon" style="${d.accent === 'violet' ? 'color:#c5b4fc;background:var(--violet-soft)' : d.accent === 'green' ? 'color:#69e1b5;background:var(--emerald-soft)' : d.accent === 'amber' ? 'color:#f6c978;background:var(--amber-soft)' : ''}">${icon('database', 18)}</span><div><h1>${esc(d.name)}</h1><p>${d.rows} rows · ${d.features} features · target: ${d.target} · ${d.type}</p></div></div><div class="workspace-actions"><button class="btn btn-ghost btn-sm" data-action="nav" data-view="datasets">${icon('database', 13)} Switch dataset</button><button class="btn btn-secondary btn-sm" data-action="open-upload">${icon('upload', 13)} Add data</button></div></section><nav class="workspace-tabs" aria-label="Dataset workspace sections">${tabs.map(([id,label]) => `<button class="tab-btn ${state.workspaceTab === id ? 'active' : ''}" data-action="workspace-tab" data-tab="${id}">${label}${id === 'history' ? `<span class="tab-badge">${datasetExperiments().length}</span>` : ''}</button>`).join('')}</nav>${renderWorkspaceContent()}</main>`;
}

function renderWorkspaceContent() {
  const content = { overview: overviewTab, explorer: explorerTab, preprocess: preprocessTab, models: modelsTab, automl: automlTab, compare: compareTab, explain: explainTab, history: historyTab }[state.workspaceTab] || overviewTab;
  return content();
}

function overviewTab() {
  const d = selectedDataset(); const exps = datasetExperiments();
  return `<div class="workspace-grid"><div><section class="panel panel-accent"><div class="panel-header"><div><span class="section-kicker">Workspace overview</span><h2 class="section-title" style="font-size:23px;margin-top:8px">The shape of <span style="color:var(--cyan)">${esc(d.short)}</span>.</h2><p class="panel-subtitle" style="font-size:11px;max-width:460px;line-height:1.65">${esc(d.description)} Explore the input, make preprocessing choices visible, then run a controlled experiment.</p></div><span class="tag amber">ILLUSTRATIVE DATA</span></div><div class="metric-row"><div class="mini-metric"><span>Rows</span><b>${d.rows}</b></div><div class="mini-metric"><span>Features</span><b>${d.features}</b></div><div class="mini-metric"><span>Missing values</span><b>0.8%</b></div><div class="mini-metric"><span>Best accuracy</span><b>${exps.length ? fmtPct(Math.max(...exps.map(e => e.accuracy))) : '—'}</b></div></div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Performance overview</h2><p class="panel-subtitle">Illustrative validation metrics from this dataset</p></div><button class="btn btn-ghost btn-sm" data-action="workspace-tab" data-tab="compare">Compare ${icon('arrow', 12)}</button></div><div id="workspace-overview-chart" class="chart-holder"></div></section></div><aside><section class="panel panel-accent violet"><div class="panel-header"><div><h2 class="panel-title">Recommended next step</h2><p class="panel-subtitle">Based on the current workspace state</p></div>${icon('spark', 15)}</div><h3 style="margin:4px 0 7px;font-size:16px">Inspect the feature signal</h3><p style="margin:0 0 16px;color:var(--muted);font-size:11px;line-height:1.65">Open Data Explorer to see distributions and correlations before changing the pipeline.</p><button class="btn btn-violet btn-sm" data-action="workspace-tab" data-tab="explorer">Open Data Explorer ${icon('arrow', 12)}</button></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Workspace map</h2><p class="panel-subtitle">A contextual path through the lab</p></div></div><div class="activity-list"><div class="activity-row"><span class="activity-icon">01</span><div><strong>Understand</strong><span>Explorer + schema</span></div><span class="tag blue">NOW</span></div><div class="activity-row"><span class="activity-icon" style="color:#c5b4fc;background:var(--violet-soft)">02</span><div><strong>Prepare</strong><span>Preprocessing studio</span></div><span class="activity-time">next</span></div><div class="activity-row"><span class="activity-icon" style="color:#69e1b5;background:var(--emerald-soft)">03</span><div><strong>Experiment</strong><span>Models + AutoML</span></div><span class="activity-time">later</span></div><div class="activity-row"><span class="activity-icon" style="color:#f6c978;background:var(--amber-soft)">04</span><div><strong>Explain</strong><span>Comparison + importance</span></div><span class="activity-time">later</span></div></div></section></aside></div>`;
}

function explorerTab() {
  const d = selectedDataset();
  const isCategorical = (column, i) => d.id === 'churn' ? ['contract', 'payment_method', 'churn'].includes(column) : i === d.columns.length - 1;
  return `<div class="workspace-grid"><div><section class="panel"><div class="panel-header"><div><span class="section-kicker">01 / inspect</span><h2 class="panel-title" style="margin-top:8px">Dataset preview</h2><p class="panel-subtitle">First five rows · values are representative samples</p></div><span class="tag blue">SCHEMA READY</span></div><div class="data-preview"><table><thead><tr>${d.columns.map((c,i) => `<th>${esc(c)}<br /><span class="type-chip">${i === d.columns.length - 1 ? 'target' : isCategorical(c, i) ? 'category' : 'float64'}</span></th>`).join('')}</tr></thead><tbody>${(mockRows[d.id] || mockRows.iris).map(row => `<tr>${row.map(v => `<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Feature distributions</h2><p class="panel-subtitle">Illustrative density view by feature</p></div><select class="select" aria-label="Distribution feature"><option>All numeric features</option><option>${esc(d.columns[0])}</option><option>${esc(d.columns[1])}</option></select></div><div id="distribution-chart" class="chart-holder"></div></section></div><aside><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Column profile</h2><p class="panel-subtitle">Types, cardinality, missingness</p></div>${icon('info', 15)}</div><div class="schema-list">${d.columns.map((c,i) => { const categorical = isCategorical(c, i); return `<div class="schema-row"><div><strong>${esc(c)}</strong><small>${i === d.columns.length - 1 ? 'categorical target' : categorical ? 'categorical feature' : 'continuous feature'}</small></div><div style="text-align:right"><span class="tag ${i === d.columns.length - 1 ? 'violet' : categorical ? 'amber' : 'blue'}">${i === d.columns.length - 1 ? 'target' : categorical ? 'category' : 'numeric'}</span><small style="display:block;margin-top:4px;color:var(--muted);font-family:var(--mono);font-size:8px">${i === d.columns.length - 1 ? (d.id === 'churn' ? '2 classes' : '3 classes') : i % 2 ? '0.0%' : '0.8%'} null</small></div></div>`; }).join('')}</div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Correlation heatmap</h2><p class="panel-subtitle">Numeric feature relationships</p></div></div><div id="heatmap-chart" class="chart-holder chart-small"></div></section><section class="section-block panel panel-accent amber"><div class="panel-header"><div><h2 class="panel-title">Target distribution</h2><p class="panel-subtitle">Useful before choosing a split</p></div><span class="tag amber">CHECK BALANCE</span></div><div id="target-chart" class="chart-holder chart-small"></div></section></aside></div>`;
}

function preprocessTab() {
  const p = state.preprocessing; const d = selectedDataset(); const featureColumns = d.columns.filter(column => column !== p.target);
  return `<div class="workspace-grid"><section class="panel"><div class="panel-header"><div><span class="section-kicker">02 / prepare</span><h2 class="panel-title" style="margin-top:8px">Preprocessing Studio</h2><p class="panel-subtitle">Configure a reproducible pipeline before you fit an estimator.</p></div><span class="tag blue">STATEFUL CONTROLS</span></div><div class="form-grid"><div class="field"><label>Target selection <span class="field-help">What should the model learn?</span></label><select class="field-select" data-setting="preprocessing.target">${d.columns.map(c => `<option ${p.target === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Missing-value handling <span class="field-help">0.8% missing in mock profile</span></label><select class="field-select" data-setting="preprocessing.missing">${['Median imputation','Mean imputation','Drop rows','Flag as feature'].map(v => `<option ${p.missing === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Categorical encoding</label><select class="field-select" data-setting="preprocessing.encoding">${['One-hot encoding','Ordinal encoding','Target encoding'].map(v => `<option ${p.encoding === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Feature scaling</label><select class="field-select" data-setting="preprocessing.scaling">${['Standard scaler','Robust scaler','Min-max scaler','No scaling'].map(v => `<option ${p.scaling === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Duplicate handling</label><select class="field-select" data-setting="preprocessing.duplicates">${['Keep first row','Drop duplicates','Flag duplicates'].map(v => `<option ${p.duplicates === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class imbalance strategy</label><select class="field-select" data-setting="preprocessing.imbalance">${['Balanced class weights','Random oversampling','SMOTE (illustrative)','No adjustment'].map(v => `<option ${p.imbalance === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Feature selection <span class="field-help">${p.features.length} of ${featureColumns.length} features selected</span></label><div class="check-grid">${featureColumns.map(c => `<label class="check-chip"><input type="checkbox" data-feature="${esc(c)}" ${p.features.includes(c) ? 'checked' : ''} />${esc(c)}</label>`).join('')}</div></div><div class="field full"><label>Train / test split <span class="range-value">${p.split}% / ${100 - p.split}%</span></label><div class="range-line"><span class="mono" style="font-size:9px;color:var(--muted)">train</span><input type="range" min="60" max="90" step="5" value="${p.split}" data-setting="preprocessing.split" aria-label="Train split percentage" /><span class="mono" style="font-size:9px;color:var(--muted)">test</span></div></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:22px;padding-top:16px;border-top:1px solid var(--line)"><button class="btn btn-ghost btn-sm" data-action="reset-preprocessing">Reset defaults</button><button class="btn btn-primary btn-sm" data-action="save-preprocessing">Apply pipeline ${icon('check', 13)}</button></div></section><aside><section class="panel panel-accent"><div class="panel-header"><div><h2 class="panel-title">Pipeline preview</h2><p class="panel-subtitle">Updates as you make choices</p></div><span class="tag green">DRAFT</span></div><div class="pipeline"><div class="pipeline-node"><strong>Input</strong><span>${esc(d.short)}.csv</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Clean</strong><span>${esc(p.missing).split(' ')[0]}</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Encode</strong><span>${esc(p.encoding).split(' ')[0]}</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Scale</strong><span>${esc(p.scaling).split(' ')[0]}</span></div></div><div style="padding-top:14px;border-top:1px solid var(--line)"><div class="stat-row"><span>Target</span><b>${esc(p.target)}</b><b>${p.split}% train</b></div><div class="stat-row"><span>Features</span><b>${p.features.length} selected</b><b>${100 - p.split}% test</b></div><div class="stat-row"><span>Strategy</span><b>${esc(p.imbalance).split(' ')[0]}</b><b>active</b></div></div></section><section class="section-block panel panel-accent amber"><div class="panel-header"><div><h2 class="panel-title">Why this matters</h2><p class="panel-subtitle">Context for technical users</p></div>${icon('info', 15)}</div><p style="margin:0;color:var(--muted);font-size:11px;line-height:1.7">Preprocessing choices are part of the experiment, not a hidden prelude. In the production app, this configuration would be versioned alongside the trained model.</p></section></aside></div>`;
}

function modelsTab() {
  const cfg = state.modelType === 'Decision Tree' ? state.modelConfig : state.rfConfig; const isTree = state.modelType === 'Decision Tree';
  const completed = state.training.status === 'complete';
  return `<div class="workspace-grid"><section class="panel"><div class="panel-header"><div><span class="section-kicker">03 / experiment</span><h2 class="panel-title" style="margin-top:8px">Model Laboratory</h2><p class="panel-subtitle">Configure a model, then run a simulated training pass.</p></div><div class="model-tabs"><button class="model-tab ${isTree ? 'active' : ''}" data-action="set-model" data-model="Decision Tree">Decision Tree</button><button class="model-tab ${!isTree ? 'active' : ''}" data-action="set-model" data-model="Random Forest">Random Forest</button></div></div><div class="form-grid">${isTree ? `<div class="field"><label>Criterion</label><select class="field-select" data-setting="model.criterion">${['gini','entropy','log_loss'].map(v => `<option ${cfg.criterion === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum depth <span class="field-help">Controls tree complexity</span></label><select class="field-select" data-setting="model.maxDepth">${['3','5','8','None'].map(v => `<option ${cfg.maxDepth === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples split</label><select class="field-select" data-setting="model.minSplit">${['2','5','10','20'].map(v => `<option ${cfg.minSplit === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples leaf</label><select class="field-select" data-setting="model.minLeaf">${['1','2','4','8'].map(v => `<option ${cfg.minLeaf === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class weight</label><select class="field-select" data-setting="model.classWeight">${['Balanced','None'].map(v => `<option ${cfg.classWeight === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div>` : `<div class="field"><label>Number of estimators <span class="field-help">More trees, more stability</span></label><select class="field-select" data-setting="rf.estimators">${['50','100','200','400'].map(v => `<option ${cfg.estimators === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum depth</label><select class="field-select" data-setting="rf.maxDepth">${['5','8','12','None'].map(v => `<option ${cfg.maxDepth === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum features</label><select class="field-select" data-setting="rf.maxFeatures">${['sqrt','log2','None'].map(v => `<option ${cfg.maxFeatures === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples split</label><select class="field-select" data-setting="rf.minSplit">${['2','5','10','20'].map(v => `<option ${cfg.minSplit === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class weight</label><select class="field-select" data-setting="rf.classWeight">${['Balanced','None'].map(v => `<option ${cfg.classWeight === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div>`}</div><div class="progress-shell"><div class="progress-top"><span>${state.training.status === 'running' ? `${state.training.phase} · please wait` : state.training.status === 'complete' ? 'Training complete · result is simulated' : 'Ready to run a controlled experiment'}</span><b>${state.training.progress}%</b></div><div class="progress-track"><div class="progress-fill ${state.training.status === 'running' ? 'loading-pulse' : ''}" style="width:${state.training.progress}%"></div></div><div class="progress-steps"><span class="progress-step ${state.training.progress > 0 ? 'done' : ''}"></span><span class="progress-step ${state.training.progress > 25 ? 'done' : state.training.progress > 0 ? 'active' : ''}"></span><span class="progress-step ${state.training.progress > 55 ? 'done' : state.training.progress > 25 ? 'active' : ''}"></span><span class="progress-step ${state.training.progress >= 100 ? 'done' : state.training.progress > 55 ? 'active' : ''}"></span></div></div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn btn-primary" data-action="train-model" ${state.training.status === 'running' ? 'disabled' : ''}>${state.training.status === 'running' ? icon('clock', 14) : icon('flask', 14)} ${state.training.status === 'running' ? 'Training in progress' : 'Train model'} </button></div></section><aside><section class="panel panel-accent green"><div class="panel-header"><div><h2 class="panel-title">Training summary</h2><p class="panel-subtitle">Predefined evaluation snapshot</p></div><span class="tag ${completed ? 'green' : 'amber'}">${completed ? 'SIMULATED RESULT' : 'PENDING'}</span></div>${completed ? `<div class="metric-row"><div class="mini-metric"><span>Accuracy</span><b>${fmtPct(state.training.result?.accuracy || .947)}</b></div><div class="mini-metric"><span>Precision</span><b>${fmtPct(state.training.result?.precision || .948)}</b></div><div class="mini-metric"><span>Recall</span><b>${fmtPct(state.training.result?.recall || .946)}</b></div><div class="mini-metric"><span>F1-score</span><b>${fmtPct(state.training.result?.f1 || .947)}</b></div></div><div style="margin-top:15px;padding-top:14px;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--muted);font-size:10px"><span>${esc(state.modelType)} · ${selectedDataset().name}</span><span class="mono">${state.training.result?.duration || '2.1s'}</span></div>` : `<div class="empty-state" style="padding:32px 10px;border:0;background:transparent"><span class="feature-icon">${icon('chart', 16)}</span><h3>Metrics will appear here</h3><p>Run the simulated training pass to populate the evaluation summary.</p></div>`}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Configuration snapshot</h2><p class="panel-subtitle">What this run would record</p></div></div><div class="stat-list"><div class="stat-row"><span>Estimator</span><b>${esc(state.modelType)}</b><b>active</b></div><div class="stat-row"><span>Target</span><b>${esc(state.preprocessing.target)}</b><b>${state.preprocessing.split}% train</b></div><div class="stat-row"><span>Features</span><b>${state.preprocessing.features.length}</b><b>${esc(state.preprocessing.scaling).split(' ')[0]}</b></div></div></section></aside></div>`;
}

function automlTab() {
  const a = state.automlConfig; const completed = state.automl.status === 'complete';
  const options = state.automlMode === 'Controlled' ? ['Decision Tree', 'Random Forest'] : ['Decision Tree', 'Random Forest', 'Extra Trees', 'HistGradientBoosting', 'Logistic Regression'];
  return `<div class="workspace-grid"><section class="panel panel-accent violet"><div class="panel-header"><div><span class="section-kicker" style="color:#c5b4fc">04 / search</span><h2 class="panel-title" style="margin-top:8px">AutoML Laboratory</h2><p class="panel-subtitle">Run an illustrative candidate search with visible constraints.</p></div><span class="tag violet">SIMULATION MODE</span></div><div class="model-tabs" style="margin-bottom:18px"><button class="model-tab ${state.automlMode === 'Controlled' ? 'active' : ''}" data-action="set-automl-mode" data-mode="Controlled">Controlled Mode</button><button class="model-tab ${state.automlMode === 'Extended' ? 'active' : ''}" data-action="set-automl-mode" data-mode="Extended">Extended Mode</button></div><div class="form-grid"><div class="field"><label>Time budget</label><select class="field-select" data-setting="automl.budget">${['2 minutes','5 minutes','10 minutes','30 minutes'].map(v => `<option ${a.budget === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Optimization metric</label><select class="field-select" data-setting="automl.metric">${['Accuracy','F1 score','Precision','Recall'].map(v => `<option ${a.metric === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field"><label>Validation strategy</label><select class="field-select" data-setting="automl.validation">${['Stratified 5-fold','Stratified 3-fold','Holdout 20%'].map(v => `<option ${a.validation === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Estimator selection <span class="field-help">Choose the search space</span></label><div class="check-grid">${options.map(v => `<label class="check-chip"><input type="checkbox" data-automl-estimator="${esc(v)}" ${a.estimators.includes(v) ? 'checked' : ''} />${v}</label>`).join('')}</div></div></div><div class="progress-shell"><div class="progress-top"><span>${state.automl.status === 'running' ? `${state.automl.phase} · exploring candidates` : completed ? 'Search complete · winner is illustrative' : `${a.estimators.length} estimators in the search space`}</span><b>${state.automl.progress}%</b></div><div class="progress-track"><div class="progress-fill violet ${state.automl.status === 'running' ? 'loading-pulse' : ''}" style="width:${state.automl.progress}%"></div></div><div class="progress-steps"><span class="progress-step ${state.automl.progress > 0 ? 'done' : ''}"></span><span class="progress-step ${state.automl.progress > 28 ? 'done' : state.automl.progress > 0 ? 'active' : ''}"></span><span class="progress-step ${state.automl.progress > 68 ? 'done' : state.automl.progress > 28 ? 'active' : ''}"></span><span class="progress-step ${state.automl.progress >= 100 ? 'done' : state.automl.progress > 68 ? 'active' : ''}"></span></div></div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn btn-violet" data-action="run-automl" ${state.automl.status === 'running' ? 'disabled' : ''}>${state.automl.status === 'running' ? icon('clock', 14) : icon('spark', 14)} ${state.automl.status === 'running' ? 'Search in progress' : 'Launch AutoML'}</button></div></section><aside><section class="panel panel-accent violet"><div class="panel-header"><div><h2 class="panel-title">Best estimator</h2><p class="panel-subtitle">Selected from mock candidates</p></div><span class="tag violet">WINNER</span></div>${completed ? `<div style="display:flex;align-items:center;gap:12px;padding:13px;border:1px solid rgba(139,92,246,.28);border-radius:9px;background:var(--violet-soft)"><span class="feature-icon" style="color:#d6c9ff;background:rgba(139,92,246,.23)">${icon('tree', 16)}</span><div><strong style="display:block;font-size:15px">Random Forest</strong><span style="display:block;margin-top:3px;color:#c5b4fc;font-family:var(--mono);font-size:9px">${a.metric} · 97.3%</span></div></div><div style="margin-top:15px" class="stat-list"><div class="stat-row"><span>n_estimators</span><b>200</b><b>sqrt</b></div><div class="stat-row"><span>max_depth</span><b>8</b><b>balanced</b></div><div class="stat-row"><span>validation</span><b>5-fold</b><b>stratified</b></div></div>` : `<div class="empty-state" style="padding:32px 10px;border:0;background:transparent"><span class="feature-icon" style="color:#c5b4fc;background:var(--violet-soft)">${icon('spark', 16)}</span><h3>Awaiting search</h3><p>Launch AutoML to surface a best estimator and its illustrative configuration.</p></div>`}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">How to read this</h2><p class="panel-subtitle">A transparent boundary</p></div>${icon('info', 15)}</div><p style="margin:0;color:var(--muted);font-size:11px;line-height:1.7">This experience mirrors the shape of an AutoML run, but it does not execute FLAML or fit real models. Use it to review the intended product workflow.</p></section></aside></div>`;
}

function compareTab() {
  const selected = datasetExperiments().filter(e => state.comparisonSelection.includes(e.id));
  return `<div class="workspace-grid"><aside><section class="panel"><div class="panel-header"><div><span class="section-kicker">05 / compare</span><h2 class="panel-title" style="margin-top:8px">Select experiments</h2><p class="panel-subtitle">Choose two or more runs to compare.</p></div><span class="tag blue">${selected.length} SELECTED</span></div><div class="selection-list">${datasetExperiments().map(e => `<label class="selection-card ${state.comparisonSelection.includes(e.id) ? 'selected' : ''}"><input type="checkbox" data-comparison="${e.id}" ${state.comparisonSelection.includes(e.id) ? 'checked' : ''} /><div><strong>${esc(e.name)}</strong><span>${esc(e.model)} · ${fmtPct(e.accuracy)} accuracy</span></div></label>`).join('')}</div>${selected.length < 2 ? `<div class="empty-state" style="margin-top:12px;padding:18px 10px"><p style="margin-bottom:0">Select at least two experiments to render the comparison surface.</p></div>` : ''}</section></aside><div><section class="panel"><div class="panel-header"><div><span class="section-kicker">Illustrative metrics</span><h2 class="panel-title" style="margin-top:8px">Performance comparison</h2><p class="panel-subtitle">Accuracy, precision, recall, and F1 · not produced by a real run</p></div><button class="btn btn-ghost btn-sm" data-action="notify-demo">${icon('download', 12)} Export view</button></div><div id="comparison-chart" class="chart-holder"></div></section><section class="section-block two-col"><div class="panel"><div class="panel-header"><div><h2 class="panel-title">Confusion matrix</h2><p class="panel-subtitle">Best selected experiment</p></div><span class="tag green">RF</span></div><div id="confusion-chart" class="chart-holder chart-small"></div></div><div class="panel"><div class="panel-header"><div><h2 class="panel-title">Run details</h2><p class="panel-subtitle">Recorded alongside metrics</p></div></div><div class="stat-list">${selected.slice(0, 3).map(e => `<div class="stat-row"><span>${esc(e.model)}</span><b>${e.duration}</b><b>${fmtPct(e.recall)} recall</b></div>`).join('') || '<div class="empty-state" style="padding:24px 0;border:0;background:transparent"><p style="margin:0">No experiment selected.</p></div>'}</div></div></section></div></div>`;
}

function explainTab() {
  const d = selectedDataset(); const featureNames = d.columns.filter(column => column !== d.target); const rows = getPredictionRows(); const prediction = rows[state.predictionIndex];
  return `<div class="workspace-grid"><div><section class="panel"><div class="panel-header"><div><span class="section-kicker">06 / explain</span><h2 class="panel-title" style="margin-top:8px">Feature importance</h2><p class="panel-subtitle">Illustrative contribution to the selected model</p></div><span class="tag amber">ILLUSTRATIVE</span></div><div id="importance-chart" class="chart-holder"></div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Decision Tree visualization</h2><p class="panel-subtitle">Simplified structure for discussion</p></div><span class="tag blue">DEPTH 3</span></div><div class="tree-diagram"><svg class="tree-lines" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M50 13 L24 48 M50 13 L76 48 M24 55 L9 84 M24 55 L38 84 M76 55 L62 84 M76 55 L91 84" stroke="rgba(56,189,248,.42)" stroke-width=".8" fill="none" /></svg><div class="tree-node root">${featureNames[2] || featureNames[0] || 'feature_3'} ≤ 2.45</div><div class="tree-node left">${featureNames[3] || featureNames[1] || 'feature_4'} ≤ 1.75</div><div class="tree-node right">${featureNames[3] || featureNames[1] || 'feature_4'} ≤ 1.65</div><div class="tree-node leaf-a">${d.id === 'iris' ? 'setosa' : 'class_0'} · 50</div><div class="tree-node leaf-b">${d.id === 'iris' ? 'versicolor' : 'class_1'} · 44</div><div class="tree-node leaf-c">${d.id === 'iris' ? 'virginica' : 'class_2'} · 42</div><div class="tree-node leaf-d">mixed · 14</div></div></section></div><aside><section class="panel panel-accent green"><div class="panel-header"><div><h2 class="panel-title">Sample prediction explorer</h2><p class="panel-subtitle">Walk through one illustrative row</p></div><span class="tag green">ROW ${state.predictionIndex + 1} / ${rows.length}</span></div><select class="field-select" data-setting="predictionIndex" style="margin-bottom:15px">${rows.map((r,i) => `<option value="${i}" ${state.predictionIndex === i ? 'selected' : ''}>${r.id} · ${r.predicted}</option>`).join('')}</select><div style="padding:14px;border:1px solid var(--line);border-radius:9px;background:rgba(255,255,255,.02)"><span class="mono" style="color:var(--muted);font-size:9px">FEATURE VECTOR</span><strong style="display:block;margin-top:8px;font-family:var(--mono);font-size:13px">${prediction.values}</strong><div style="display:flex;justify-content:space-between;gap:10px;margin-top:17px;color:var(--muted);font-size:10px"><span>Predicted</span><b style="color:var(--cyan)">${prediction.predicted}</b></div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:7px;color:var(--muted);font-size:10px"><span>Actual label</span><b style="color:${prediction.actual === prediction.predicted ? 'var(--emerald)' : 'var(--amber)'}">${prediction.actual}</b></div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:7px;color:var(--muted);font-size:10px"><span>Top probability</span><b style="color:var(--text)">${fmtPct(prediction.probability)}</b></div></div><div style="margin-top:15px"><div style="display:flex;justify-content:space-between;color:var(--muted);font-size:9px;margin-bottom:6px"><span>Prediction probability</span><span class="mono">${fmtPct(prediction.probability)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${prediction.probability * 100}%"></div></div></div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Permutation importance</h2><p class="panel-subtitle">Illustrative sensitivity signal</p></div>${icon('info', 15)}</div><div id="permutation-chart" class="chart-holder chart-small"></div></section></aside></div>`;
}

function historyTab() {
  const exps = datasetExperiments();
  return `<section class="panel"><div class="panel-header"><div><span class="section-kicker">07 / trace</span><h2 class="panel-title" style="margin-top:8px">Experiment History</h2><p class="panel-subtitle">A record of simulated runs associated with ${esc(selectedDataset().name)}</p></div><button class="btn btn-ghost btn-sm" data-action="notify-demo">${icon('filter', 12)} Filter history</button></div><div class="history-table"><table><thead><tr><th>Experiment</th><th>Model</th><th>Accuracy</th><th>F1-score</th><th>Duration</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody>${exps.length ? exps.map(e => `<tr><td><strong style="display:block;color:var(--text-soft);font-size:10px">${esc(e.name)}</strong><span style="display:block;margin-top:3px;color:var(--muted);font-size:9px">${esc(selectedDataset().short)} · ${e.simulated ? 'simulated' : 'session run'}</span></td><td>${esc(e.model)}</td><td class="mono">${fmtPct(e.accuracy)}</td><td class="mono">${fmtPct(e.f1)}</td><td class="mono">${e.duration}</td><td>${e.date}</td><td><span class="status status-success"><span class="dot"></span>${e.status}</span></td><td><button class="icon-btn" data-action="experiment-detail" data-id="${e.id}" aria-label="View experiment details">${icon('external', 13)}</button></td></tr>`).join('') : `<tr><td colspan="8"><div class="empty-state" style="border:0;background:transparent"><span class="feature-icon">${icon('clock', 16)}</span><h3>No experiment history yet</h3><p>Run a model or AutoML simulation to create a session record.</p></div></td></tr>`}</tbody></table></div></section>`;
}

function renderModal() {
  if (state.activeModal === 'upload') {
    modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="upload-title" onclick="event.stopPropagation()"><div class="modal-header"><div><h2 id="upload-title">Upload a dataset</h2><p>Bring a CSV into the prototype workspace. No file is processed on a server.</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close modal">${icon('close', 16)}</button></div><div class="modal-body">${state.upload.status === 'idle' ? `<div class="dropzone" id="dropzone"><span class="feature-icon">${icon('upload', 18)}</span><strong>Drop a CSV here to profile it</strong><p>or choose a local file · session-only mock upload</p><label class="btn btn-secondary btn-sm" for="csv-file">Choose CSV file ${icon('arrow', 12)}</label><input id="csv-file" class="hidden-input" type="file" accept=".csv,text/csv" /></div><div style="display:flex;align-items:flex-start;gap:9px;margin-top:14px;color:var(--muted);font-size:10px;line-height:1.5">${icon('info', 13)} <span>This interaction simulates reading, profiling, and readiness. It does not parse or store the selected file.</span></div>` : `<div class="progress-shell" style="margin-top:0"><div class="progress-top"><span>${state.upload.status === 'complete' ? 'Dataset ready for review' : `${state.upload.fileName || 'sample.csv'} · profiling`}</span><b>${state.upload.progress}%</b></div><div class="progress-track"><div class="progress-fill ${state.upload.status === 'running' ? 'loading-pulse' : ''}" style="width:${state.upload.progress}%"></div></div><div class="progress-steps"><span class="progress-step ${state.upload.progress > 0 ? 'done' : ''}"></span><span class="progress-step ${state.upload.progress > 30 ? 'done' : state.upload.progress > 0 ? 'active' : ''}"></span><span class="progress-step ${state.upload.progress >= 100 ? 'done' : state.upload.progress > 30 ? 'active' : ''}"></span></div><p style="margin:13px 0 0;color:var(--muted);font-size:10px;line-height:1.5">${state.upload.status === 'complete' ? 'Mock profile created. You can keep exploring or upload another sample.' : state.upload.progress < 35 ? 'Reading file header…' : state.upload.progress < 75 ? 'Profiling columns and target candidates…' : 'Preparing workspace metadata…'}</p></div>`}</div><div class="modal-footer"><button class="btn btn-ghost btn-sm" data-action="close-modal">Cancel</button>${state.upload.status === 'complete' ? `<button class="btn btn-primary btn-sm" data-action="open-new-dataset">Open new workspace ${icon('arrow', 12)}</button>` : ''}</div></section></div>`;
    wireDropzone();
  } else if (state.activeModal === 'experiment') {
    const e = state.experiments.find(x => x.id === state.modalExperimentId) || state.experiments[0];
    modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" onclick="event.stopPropagation()"><div class="modal-header"><div><h2>Experiment detail</h2><p>${esc(e.name)} · saved in prototype history</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close modal">${icon('close', 16)}</button></div><div class="modal-body"><div class="metric-row"><div class="mini-metric"><span>Accuracy</span><b>${fmtPct(e.accuracy)}</b></div><div class="mini-metric"><span>Precision</span><b>${fmtPct(e.precision)}</b></div><div class="mini-metric"><span>Recall</span><b>${fmtPct(e.recall)}</b></div><div class="mini-metric"><span>F1-score</span><b>${fmtPct(e.f1)}</b></div></div><div class="stat-list" style="margin-top:18px"><div class="stat-row"><span>Dataset</span><b>${esc(selectedDataset().name)}</b><b>${esc(selectedDataset().target)}</b></div><div class="stat-row"><span>Model</span><b>${esc(e.model)}</b><b>${e.duration}</b></div><div class="stat-row"><span>Status</span><b>${e.status}</b><b>${e.simulated ? 'simulated' : 'session'}</b></div></div><div style="margin-top:17px;padding:12px;border:1px solid rgba(245,158,11,.22);border-radius:9px;background:var(--amber-soft);color:#d3b475;font-size:10px;line-height:1.55">${icon('info', 12)} This experiment record is illustrative. A production version would link this result to a persisted model artifact and preprocessing configuration.</div></div><div class="modal-footer"><button class="btn btn-primary btn-sm" data-action="close-modal">Done</button></div></section></div>`;
  }
}

function wireDropzone() {
  const zone = document.getElementById('dropzone');
  const input = document.getElementById('csv-file');
  if (!zone || !input) return;
  input.addEventListener('change', e => {
    const file = e.target.files && e.target.files[0];
    if (file) startUpload(file.name);
  });
  ['dragenter', 'dragover'].forEach(type => zone.addEventListener(type, e => { e.preventDefault(); zone.classList.add('dragging'); }));
  ['dragleave', 'drop'].forEach(type => zone.addEventListener(type, e => { e.preventDefault(); zone.classList.remove('dragging'); }));
  zone.addEventListener('drop', e => {
    const file = e.dataTransfer.files && e.dataTransfer.files[0];
    if (file) startUpload(file.name);
  });
}

function startUpload(fileName = 'sample_dataset.csv') {
  clearInterval(uploadTimer);
  state.upload = { status: 'running', progress: 8, fileName, datasetId: null };
  render();
  uploadTimer = setInterval(() => {
    state.upload.progress = Math.min(100, state.upload.progress + 18);
    if (state.upload.progress >= 100) {
      clearInterval(uploadTimer);
      const id = `upload-${Date.now()}`;
      const baseName = fileName.replace(/\.csv$/i, '').replace(/[_-]+/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase());
      datasets.push({ id, name: baseName || 'Uploaded Dataset', short: 'uploaded', type: 'Classification', rows: '—', features: '—', target: 'target', size: 'session file', updated: 'Just now', accent: 'blue', description: 'Session-only mock dataset created by the upload simulation.', columns: ['feature_1', 'feature_2', 'feature_3', 'target'] });
      state.upload.datasetId = id;
      state.upload.status = 'complete';
      render();
      notify('Dataset profiled', `${fileName} is ready as a session-only mock dataset.`, 'success');
    } else {
      render();
    }
  }, 520);
}

function startTraining() {
  if (state.training.status === 'running') return;
  clearInterval(trainingTimer);
  state.training = { status: 'running', progress: 6, phase: 'Preparing split', modelType: state.modelType, result: null, datasetId: state.selectedDatasetId };
  render();
  const phases = [[6, 'Preparing split'], [30, 'Preparing split'], [53, 'Fitting estimator'], [78, 'Scoring holdout'], [100, 'Complete']];
  let step = 0;
  trainingTimer = setInterval(() => {
    const next = phases[Math.min(step, phases.length - 1)];
    state.training.progress = next[0]; state.training.phase = next[1]; step += 1;
    if (state.training.progress >= 100) {
      clearInterval(trainingTimer);
      state.training.status = 'complete';
      const d = selectedDataset();
      state.training.modelType = state.modelType;
      state.training.result = { accuracy: state.modelType === 'Decision Tree' ? .947 : .973, precision: state.modelType === 'Decision Tree' ? .948 : .971, recall: state.modelType === 'Decision Tree' ? .946 : .972, f1: state.modelType === 'Decision Tree' ? .947 : .971, duration: state.modelType === 'Decision Tree' ? '2.1s' : '8.4s' };
      state.training.datasetId = d.id;
      const id = `exp-session-${Date.now()}`;
      state.experiments.unshift({ id, name: `${d.short} · ${state.modelType} session`, datasetId: d.id, model: state.modelType, accuracy: state.modelType === 'Decision Tree' ? .947 : .973, precision: state.modelType === 'Decision Tree' ? .948 : .971, recall: state.modelType === 'Decision Tree' ? .946 : .972, f1: state.modelType === 'Decision Tree' ? .947 : .971, duration: state.modelType === 'Decision Tree' ? '2.1s' : '8.4s', date: 'Just now', status: 'Completed', simulated: true });
      state.comparisonSelection = datasetExperiments(d.id).slice(0, 2).map(e => e.id);
      render();
      notify('Training simulation complete', `${state.modelType} returned an illustrative validation score of ${state.modelType === 'Decision Tree' ? '94.7%' : '97.3%'}.`, 'success');
    } else {
      render();
    }
  }, 630);
}

function startAutoML() {
  if (state.automl.status === 'running') return;
  clearInterval(automlTimer);
  state.automl = { status: 'running', progress: 5, phase: 'Searching candidates', datasetId: state.selectedDatasetId };
  render();
  const phases = [[5, 'Searching candidates'], [34, 'Searching candidates'], [70, 'Validating trials'], [88, 'Selecting winner'], [100, 'Complete']];
  let step = 0;
  automlTimer = setInterval(() => {
    const next = phases[Math.min(step, phases.length - 1)];
    state.automl.progress = next[0]; state.automl.phase = next[1]; step += 1;
    if (state.automl.progress >= 100) {
      clearInterval(automlTimer);
      state.automl.status = 'complete';
      const d = selectedDataset();
      const id = `exp-automl-${Date.now()}`;
      state.experiments.unshift({ id, name: `${d.short} · AutoML winner`, datasetId: d.id, model: 'Random Forest', accuracy: .973, precision: .971, recall: .972, f1: .971, duration: '1m 08s', date: 'Just now', status: 'Completed', simulated: true });
      render();
      notify('AutoML simulation complete', 'Random Forest surfaced as the illustrative winner for review.', 'success');
    } else {
      render();
    }
  }, 730);
}

function plot(id, data, layout = {}) {
  const el = document.getElementById(id);
  if (!el || !window.Plotly) return;
  const base = { paper_bgcolor: 'transparent', plot_bgcolor: 'transparent', font: { family: 'Inter, sans-serif', color: '#95a3b9', size: 10 }, margin: { l: 38, r: 14, t: 12, b: 32 }, showlegend: false, hoverlabel: { bgcolor: '#172033', bordercolor: '#31435d', font: { color: '#f1f5f9', size: 10 } }, xaxis: { gridcolor: 'rgba(148,163,184,.1)', zerolinecolor: 'transparent', tickfont: { size: 9 } }, yaxis: { gridcolor: 'rgba(148,163,184,.1)', zerolinecolor: 'transparent', tickfont: { size: 9 } }, ...layout };
  window.Plotly.newPlot(el, data, base, { responsive: true, displayModeBar: false, scrollZoom: false });
}
function renderCharts() {
  if (state.view === 'dashboard') {
    plot('dashboard-performance-chart', [{ x: ['Oct 10', 'Oct 14', 'Oct 18', 'Oct 22', 'Oct 26', 'Oct 30', 'Nov 03', 'Nov 07'], y: [.82, .84, .86, .84, .89, .9, .92, .973], type: 'scatter', mode: 'lines+markers', line: { color: '#38bdf8', width: 2.5, shape: 'spline' }, marker: { color: '#38bdf8', size: 5 }, fill: 'tozeroy', fillcolor: 'rgba(56,189,248,.08)', hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }], { yaxis: { tickformat: '.0%', range: [.75, 1] }, xaxis: { showgrid: false }, margin: { l: 40, r: 10, t: 10, b: 30 } });
  }
  if (state.view !== 'workspace') return;
  if (state.workspaceTab === 'overview') {
    const exps = datasetExperiments();
    plot('workspace-overview-chart', [{ x: exps.map(e => e.model), y: exps.map(e => e.accuracy), type: 'bar', marker: { color: exps.map((_, i) => i === 0 ? '#38bdf8' : '#506887'), line: { color: 'rgba(255,255,255,.12)', width: 1 } }, hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }], { yaxis: { tickformat: '.0%', range: [.8, 1] }, xaxis: { tickfont: { size: 9 } } });
  }
  if (state.workspaceTab === 'explorer') {
    const d = selectedDataset();
    const heatLabels = d.columns.slice(0, Math.min(4, d.columns.length - 1)).map(label => label.length > 10 ? label.slice(0, 10) : label);
    const targetLabels = d.id === 'churn' ? ['No', 'Yes'] : d.id === 'breast' ? ['benign', 'malignant'] : d.id === 'juice' ? ['class_0', 'class_1', 'class_2'] : ['setosa', 'versicolor', 'virginica'];
    const targetValues = d.id === 'churn' ? [5174, 1869] : d.id === 'breast' ? [357, 212] : d.id === 'juice' ? [59, 71, 48] : [50, 50, 50];
    const matrixSize = heatLabels.length;
    const heatZ = Array.from({ length: matrixSize }, (_, r) => heatLabels.map((_, c) => r === c ? 1 : Number((0.1 + (((r + 2) * (c + 3)) % 7) / 10).toFixed(2))));
    plot('distribution-chart', [{ x: [4.2, 4.8, 5.1, 5.4, 5.7, 6.0, 6.3, 6.7, 7.0, 7.4], y: [1, 2, 4, 6, 9, 8, 7, 5, 3, 1], type: 'scatter', mode: 'lines', line: { color: '#38bdf8', width: 2.5, shape: 'spline' }, fill: 'tozeroy', fillcolor: 'rgba(56,189,248,.1)', hovertemplate: '%{x}<br><b>%{y} samples</b><extra></extra>' }, { x: [1.2, 1.8, 2.2, 2.6, 3.0, 3.4, 3.8], y: [1, 3, 6, 7, 5, 3, 1], type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 2, shape: 'spline' }, fill: 'tozeroy', fillcolor: 'rgba(139,92,246,.08)', hovertemplate: '%{x}<br><b>%{y} samples</b><extra></extra>' }], { xaxis: { title: { text: 'value', font: { size: 9 } } }, yaxis: { title: { text: 'density', font: { size: 9 } } } });
    plot('heatmap-chart', [{ z: heatZ, x: heatLabels, y: heatLabels, type: 'heatmap', colorscale: [[0, '#182338'], [.45, '#235c7c'], [1, '#38bdf8']], zmin: 0, zmax: 1, hovertemplate: '%{y} × %{x}<br><b>%{z:.2f}</b><extra></extra>' }], { margin: { l: 55, r: 5, t: 5, b: 32 }, xaxis: { tickfont: { size: 8 } }, yaxis: { tickfont: { size: 8 } } });
    plot('target-chart', [{ x: targetLabels, y: targetValues, type: 'bar', marker: { color: ['#38bdf8', '#8b5cf6', '#10b981'], line: { color: 'rgba(255,255,255,.12)', width: 1 } }, hovertemplate: '%{x}<br><b>%{y} rows</b><extra></extra>' }], { yaxis: { dtick: d.id === 'churn' ? 2000 : 25 }, xaxis: { tickfont: { size: 8 } }, margin: { l: 35, r: 5, t: 5, b: 26 } });
  }
  if (state.workspaceTab === 'compare') {
    const selected = datasetExperiments().filter(e => state.comparisonSelection.includes(e.id));
    const d = selectedDataset(); const confusionLabels = d.id === 'churn' ? ['No', 'Yes'] : d.id === 'breast' ? ['benign', 'malignant'] : d.id === 'juice' ? ['class_0', 'class_1', 'class_2'] : ['setosa', 'versicolor', 'virginica'];
    const confusionZ = confusionLabels.length === 2 ? [[322, 35], [21, 191]] : confusionLabels.length === 3 ? [[46, 2, 0], [1, 47, 2], [0, 1, 49]] : [[46, 2], [1, 47]];
    plot('comparison-chart', [{ x: selected.map(e => e.model), y: selected.map(e => e.accuracy), name: 'Accuracy', type: 'bar', marker: { color: '#38bdf8' }, hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }, { x: selected.map(e => e.model), y: selected.map(e => e.f1), name: 'F1', type: 'bar', marker: { color: '#8b5cf6' }, hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }, { x: selected.map(e => e.model), y: selected.map(e => e.precision), name: 'Precision', type: 'bar', marker: { color: '#10b981' }, hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }, { x: selected.map(e => e.model), y: selected.map(e => e.recall), name: 'Recall', type: 'bar', marker: { color: '#f59e0b' }, hovertemplate: '%{x}<br><b>%{y:.1%}</b><extra></extra>' }], { barmode: 'group', yaxis: { tickformat: '.0%', range: [.8, 1] }, legend: { orientation: 'h', y: 1.1, x: 0, font: { size: 9 } } });
    plot('confusion-chart', [{ z: confusionZ, x: confusionLabels, y: confusionLabels, type: 'heatmap', colorscale: [[0, '#101b2e'], [.55, '#245e7c'], [1, '#10b981']], showscale: false, hovertemplate: 'actual %{y}<br>predicted %{x}<br><b>%{z} rows</b><extra></extra>' }], { margin: { l: 48, r: 5, t: 4, b: 32 }, xaxis: { tickfont: { size: 8 } }, yaxis: { tickfont: { size: 8 } } });
  }
  if (state.workspaceTab === 'explain') {
    const d = selectedDataset(); const labels = d.columns.filter(column => column !== d.target).slice(0, 4); const values = labels.map((_, i) => [.42, .31, .18, .09][i] || .08); plot('importance-chart', [{ x: values, y: labels, type: 'bar', orientation: 'h', marker: { color: ['#38bdf8', '#3b82f6', '#8b5cf6', '#506887'] }, hovertemplate: '%{y}<br><b>%{x:.2f}</b><extra></extra>' }], { xaxis: { range: [0, .5], tickformat: '.0%' }, yaxis: { autorange: 'reversed', tickfont: { size: 9 } }, margin: { l: 92, r: 12, t: 10, b: 28 } });
    plot('permutation-chart', [{ x: labels.map((_, i) => [.34, .24, .16, .08][i] || .06), y: labels, type: 'bar', orientation: 'h', marker: { color: '#8b5cf6' }, hovertemplate: '%{y}<br><b>%{x:.2f}</b><extra></extra>' }], { xaxis: { range: [0, .4], tickformat: '.0%' }, yaxis: { autorange: 'reversed', tickfont: { size: 8 } }, margin: { l: 92, r: 8, t: 4, b: 25 } });
  }
}

function updateSetting(key, value) {
  const parts = key.split('.');
  if (parts[0] === 'predictionIndex') state.predictionIndex = Number(value);
  else if (parts[0] === 'preprocessing') { state.preprocessing[parts[1]] = parts[1] === 'split' ? Number(value) : value; if (parts[1] === 'target') state.preprocessing.features = state.preprocessing.features.filter(feature => feature !== value); }
  else if (parts[0] === 'model') state.modelConfig[parts[1]] = value;
  else if (parts[0] === 'rf') state.rfConfig[parts[1]] = value;
  else if (parts[0] === 'automl') state.automlConfig[parts[1]] = value;
}

app.addEventListener('click', e => {
  const target = e.target.closest('[data-action]');
  if (!target) return;
  const action = target.dataset.action;
  if (action === 'enter-app' || action === 'go-home') { setView('dashboard'); return; }
  if (action === 'scroll-workflow') { document.getElementById('workflow')?.scrollIntoView({ behavior: 'smooth' }); return; }
  if (action === 'notify-demo') { notify('Prototype interaction', 'This control is wired to the simulated TreeLab state.', 'info'); return; }
  if (action === 'nav') { setView(target.dataset.view); return; }
  if (action === 'open-dataset') { openWorkspace(target.dataset.id); return; }
  if (action === 'workspace-tab') { openWorkspace(state.selectedDatasetId, target.dataset.tab); return; }
  if (action === 'open-upload') { state.activeModal = 'upload'; state.upload = { status: 'idle', progress: 0, fileName: '', datasetId: null }; render(); return; }
  if (action === 'close-modal') { state.activeModal = null; render(); return; }
  if (action === 'clear-dataset-search') { state.search = ''; state.filter = 'All datasets'; render(); return; }
  if (action === 'dataset-menu') { notify('Dataset actions', 'Open workspace is the primary action in this prototype.', 'info'); return; }
  if (action === 'open-new-dataset') { const id = state.upload.datasetId || 'iris'; state.activeModal = null; state.selectedDatasetId = id; syncDatasetState(id); state.view = 'workspace'; state.workspaceTab = 'overview'; render(); notify('Workspace opened', 'Your uploaded file is now represented as a session-only dataset workspace.', 'success'); return; }
  if (action === 'set-model') { state.modelType = target.dataset.model; state.training = { status: 'idle', progress: 0, phase: '', modelType: '', result: null, datasetId: state.selectedDatasetId }; render(); return; }
  if (action === 'train-model') { startTraining(); return; }
  if (action === 'set-automl-mode') { state.automlMode = target.dataset.mode; state.automl = { status: 'idle', progress: 0, phase: '', datasetId: state.selectedDatasetId };  if (state.automlMode === 'Controlled') state.automlConfig.estimators = ['Decision Tree', 'Random Forest']; render(); return; }
  if (action === 'run-automl') { startAutoML(); return; }
  if (action === 'reset-preprocessing') { state.preprocessing = { target: selectedDataset().target, missing: 'Median imputation', encoding: 'One-hot encoding', scaling: 'Standard scaler', duplicates: 'Keep first row', imbalance: 'Balanced class weights', split: 80, features: selectedDataset().columns.filter(column => column !== selectedDataset().target) }; render(); notify('Pipeline reset', 'Default preprocessing choices restored.', 'info'); return; }
  if (action === 'save-preprocessing') { notify('Pipeline updated', 'The simulated pipeline is ready to use in the next experiment.', 'success'); return; }
  if (action === 'experiment-detail') { state.activeModal = 'experiment'; state.modalExperimentId = target.dataset.id; render(); return; }
  if (action === 'dismiss-toast') { state.toasts = state.toasts.filter(t => t.id !== target.dataset.toastId); renderToasts(); return; }
});

document.addEventListener('input', e => {
  if (e.target.id === 'dataset-search') { state.search = e.target.value; render(); const el = document.getElementById('dataset-search'); if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }
  if (e.target.matches('input[type="range"][data-setting]')) { updateSetting(e.target.dataset.setting, e.target.value); render(); }
});

document.addEventListener('change', e => {
  if (e.target.id === 'dataset-filter') { state.filter = e.target.value; render(); }
  if (e.target.matches('[data-setting]') && !e.target.matches('input[type="range"]')) { updateSetting(e.target.dataset.setting, e.target.value); render(); }
  if (e.target.matches('[data-feature]')) { const feature = e.target.dataset.feature; if (e.target.checked && !state.preprocessing.features.includes(feature)) state.preprocessing.features.push(feature); if (!e.target.checked) state.preprocessing.features = state.preprocessing.features.filter(f => f !== feature); render(); }
  if (e.target.matches('[data-comparison]')) { const id = e.target.dataset.comparison; if (e.target.checked && !state.comparisonSelection.includes(id)) state.comparisonSelection.push(id); if (!e.target.checked) state.comparisonSelection = state.comparisonSelection.filter(x => x !== id); render(); }
  if (e.target.matches('[data-automl-estimator]')) { const estimator = e.target.dataset.automlEstimator; if (e.target.checked && !state.automlConfig.estimators.includes(estimator)) state.automlConfig.estimators.push(estimator); if (!e.target.checked) state.automlConfig.estimators = state.automlConfig.estimators.filter(x => x !== estimator); render(); }
});

modalRoot.addEventListener('click', e => {
  const target = e.target.closest('[data-action]');
  if (!target) return;
  if (target.dataset.action === 'close-modal') { state.activeModal = null; render(); }
  if (target.dataset.action === 'open-new-dataset') { const id = state.upload.datasetId || 'iris'; state.activeModal = null; state.selectedDatasetId = id; syncDatasetState(id); state.view = 'workspace'; state.workspaceTab = 'overview'; render(); notify('Workspace opened', 'Your uploaded file is now represented as a session-only dataset workspace.', 'success'); }
}, true);

render();
